type ScreenArchetype = typeof SCREEN_ARCHETYPES[number];

// ─── Slot System ─────────────────────────────────────────────────────────────
const SLOT_TYPES = [
    "app_header", "hero_banner", "stat_group", "content_list", "content_grid",
    "horizontal_rail", "action_bar", "nav_bar", "section_header", "media_player",
    "profile_header", "form_section", "empty_state", "banner_alert", "segmented_tabs",
    "timeline_list", "settings_list", "chart_section", "social_feed_slot", "gallery_grid",
    "onboarding_step", "search_bar", "fab_button", "card_detail", "pricing_table",
    "calendar_strip", "progress_section", "testimonial_rail", "feature_grid",
    "comparison_table", "countdown_timer", "weather_widget", "map_preview",
    "notification_list", "chat_bubble_list", "story_rail", "avatar_group",
    "breadcrumb_nav", "split_view", "floating_card",
] as const;
type SlotType = typeof SLOT_TYPES[number];
const VALID_SLOT_TYPES = new Set<string>(SLOT_TYPES);

type SlotPosition = "top" | "body" | "bottom" | "overlay";

type SlotPlan = {
    slotType: SlotType;
    position: SlotPosition;
    intent: string;
    itemCount?: number; // how many rows/cards/items for list-like slots
    variant_hint?: string; // free-text hint the planner gives to the generator: "circular gauges", "card-style rows", etc.
};

type PromptRequirement = {
    requirementKey?: string;
    slotType: SlotType;
    position: SlotPosition;
    mustInclude: string;
    variantHint?: string;
    railSpec?: {
        variant: RailVariant;
        itemShape: "square" | "portrait" | "circle" | "pill" | "landscape";
        textRows: number;
    };
    itemCount?: number;
    sourceIndex: number;
};

type DesignManifest = {
    rawPrompt: string;
    requirements: PromptRequirement[];
    hardRules: string[];
};

type ScreenPlan = {
    archetype: ScreenArchetype;
    slots: SlotPlan[];
    canvas_settings?: CanvasSettings;
};

type RailVariant = "poster" | "media_track" | "circular_people" | "chips" | "landscape";

type CanvasSettings = {
    statusBarVisible?: boolean;
    statusBarTopSafeArea?: boolean;
    canvasColorScheme?: "light" | "dark";
};

// ─── Slot Constraints ────────────────────────────────────────────────────────
// Each slot type defines structural rules. The LLM is free to lay out however
// it wants WITHIN these constraints. Validation enforces them post-generation.

type SlotConstraint = {
    allowedRoots: string[];
    maxDepth: number;
    requiredTextCount?: number; // minimum # of Text nodes
    requiresSymbol?: boolean;
    maxChildren?: number; // at root level
    fullWidth?: boolean;
    description: string; // human-readable, included in the generation prompt
};

