// ═════════════════════════════════════════════════════════════════════════════
// SCREEN ASSEMBLY
// ═════════════════════════════════════════════════════════════════════════════

const ALL_RAIL_VARIANTS: RailVariant[] = ["media_track", "circular_people", "poster", "landscape", "chips"];

function pickDistinctRailVariant(used: Set<RailVariant>, preferred: RailVariant[]): RailVariant {
    for (const p of preferred) {
        if (!used.has(p)) return p;
    }
    for (const candidate of ALL_RAIL_VARIANTS) {
        if (!used.has(candidate)) return candidate;
    }
    return preferred[0] ?? "poster";
}

async function enforceRailDiversityAcrossSlots(params: {
    supabase: ReturnType<typeof createClient> | null;
    prompt: string;
    theme: ThemeTokens;
    plan: ScreenPlan;
    plannedSlots: SlotPlan[];
    slotResults: Array<{ component: AnyComponent; exemplarIds: string[] }>;
    deadlineAt: number;
}): Promise<Array<{ component: AnyComponent; exemplarIds: string[] }>> {
    const railIndices = params.plannedSlots
        .map((slot, i) => ({ slot, i }))
        .filter(({ slot }) => slot.slotType === "horizontal_rail")
        .map(({ i }) => i);
    if (railIndices.length <= 1) return params.slotResults;

    const manifest = buildDesignManifest(params.prompt);
    const usedVariants = new Set<RailVariant>();
    const nextResults = [...params.slotResults];

    for (const idx of railIndices) {
        const slot = params.plannedSlots[idx];
        const reqs = selectPromptRequirementsForSlot(slot, manifest.requirements);
        const preferred = reqs.map((r) => detectRailVariantFromRequirement(r));
        const actual = inferRailVariantFromComponent(nextResults[idx].component);

        if (!usedVariants.has(actual)) {
            usedVariants.add(actual);
            continue;
        }

        const forced = pickDistinctRailVariant(usedVariants, preferred);
        const forcedSlot: SlotPlan = {
            ...slot,
            variant_hint: `${slot.variant_hint ?? ""} | force distinct rail morphology: ${forced}`,
        };

        const remaining = params.deadlineAt - Date.now();
        if (remaining > 3800) {
            try {
                const forcedPlan: ScreenPlan = {
                    ...params.plan,
                    slots: params.plannedSlots.map((s, i) => (i === idx ? forcedSlot : s)),
                };
                const regenerated = await generateSlot({
                    supabase: params.supabase,
                    prompt: params.prompt,
                    theme: params.theme,
                    plan: forcedPlan,
                    slot: forcedSlot,
                });
                nextResults[idx] = regenerated;
                usedVariants.add(inferRailVariantFromComponent(regenerated.component));
                continue;
            } catch {
                // fall through to deterministic fallback
            }
        }

        nextResults[idx] = { component: buildFallbackSlot(forcedSlot, params.theme), exemplarIds: [] };
        usedVariants.add(forced);
    }

    return nextResults;
}

async function buildGeneratedScreen(
    supabase: ReturnType<typeof createClient> | null,
    prompt: string,
    context: unknown,
    mode: GenerationMode,
): Promise<{
    components: AnyComponent[];
    canvas_settings: CanvasSettings;
    theme?: ThemeTokens;
    exemplarsUsed?: string[];
}> {
    const deadlineAt = Date.now() + GENERATION_DEADLINE_MS;
    const withDeadline = async <T>(work: Promise<T>, stage: string): Promise<T> => {
        const remaining = deadlineAt - Date.now();
        if (remaining <= 0) throw new Error(`Generation deadline exceeded before ${stage}`);
        let timer: ReturnType<typeof setTimeout> | undefined;
        const timeout = new Promise<T>((_, reject) => {
            timer = setTimeout(() => reject(new Error(`Generation timed out during ${stage}`)), remaining);
        });
        try {
            return await Promise.race([work, timeout]);
        } finally {
            if (timer !== undefined) clearTimeout(timer);
        }
    };

    if (mode === "full_canvas") {
        // Step 1: Archetype + Theme in parallel
        const [archetype, theme] = await withDeadline(Promise.all([
            classifyArchetype(prompt),
            extractThemeTokens(prompt),
        ]), "archetype/theme");

        // Step 2: Plan slots (informed by archetype + theme)
        const plan = await withDeadline(planSlots(prompt, archetype, theme, context), "slot planning");
        const plannedSlots = plan.slots.slice(0, MAX_GENERATION_SLOTS);

        // Step 3: Generate slots in smaller batches to reduce timeout risk
        const slotResults: Array<{ component: AnyComponent; exemplarIds: string[] }> = [];
        for (let i = 0; i < plannedSlots.length; i += SLOT_BATCH_SIZE) {
            const batch = plannedSlots.slice(i, i + SLOT_BATCH_SIZE);
            if ((deadlineAt - Date.now()) <= SLOT_BATCH_GRACE_MS) {
                slotResults.push(...batch.map((slot) => ({ component: buildFallbackSlot(slot, theme), exemplarIds: [] })));
                continue;
            }
            try {
                const batchResults = await withDeadline(
                    Promise.all(batch.map((slot) => generateSlot({ supabase, prompt, theme, plan, slot }))),
                    `slot batch ${Math.floor(i / SLOT_BATCH_SIZE) + 1}`,
                );
                slotResults.push(...batchResults);
            } catch {
                slotResults.push(...batch.map((slot) => ({ component: buildFallbackSlot(slot, theme), exemplarIds: [] })));
            }
        }

        let diversifiedResults = slotResults;
        try {
            diversifiedResults = await withDeadline(
                enforceRailDiversityAcrossSlots({
                    supabase,
                    prompt,
                    theme,
                    plan,
                    plannedSlots,
                    slotResults,
                    deadlineAt,
                }),
                "rail diversity pass",
            );
        } catch {
            diversifiedResults = slotResults;
        }

        // Step 4: Assemble
        const slotComponents = diversifiedResults.map((r, i) => ({
            position: plannedSlots[i].position,
            component: r.component,
        }));

        const screen = assembleScreen(slotComponents);
        return {
            components: screen.components,
            canvas_settings: plan.canvas_settings ?? { statusBarVisible: true, statusBarTopSafeArea: true },
            theme,
            exemplarsUsed: diversifiedResults.flatMap((r) => r.exemplarIds),
        };
    }

    // Standard mode — simpler pipeline, still uses slots
    const [tokens, archetype] = await withDeadline(Promise.all([
        generateScreenTokens(prompt),
        classifyArchetype(prompt),
    ]), "tokens/archetype");

    const theme = buildBaselineTheme(tokens);
    const plan = await withDeadline(planSlots(prompt, archetype, theme, context), "slot planning");
    const plannedSlots = plan.slots.slice(0, MAX_GENERATION_SLOTS);

    const slotResults: Array<{ component: AnyComponent; exemplarIds: string[] }> = [];
    for (let i = 0; i < plannedSlots.length; i += SLOT_BATCH_SIZE) {
        const batch = plannedSlots.slice(i, i + SLOT_BATCH_SIZE);
        if ((deadlineAt - Date.now()) <= SLOT_BATCH_GRACE_MS) {
            slotResults.push(...batch.map((slot) => ({ component: buildFallbackSlot(slot, theme), exemplarIds: [] })));
            continue;
        }
        try {
            const batchResults = await withDeadline(
                Promise.all(batch.map((slot) => generateSlot({ supabase, prompt, theme, plan, slot }))),
                `slot batch ${Math.floor(i / SLOT_BATCH_SIZE) + 1}`,
            );
            slotResults.push(...batchResults);
        } catch {
            slotResults.push(...batch.map((slot) => ({ component: buildFallbackSlot(slot, theme), exemplarIds: [] })));
        }
    }

    let diversifiedResults = slotResults;
    try {
        diversifiedResults = await withDeadline(
            enforceRailDiversityAcrossSlots({
                supabase,
                prompt,
                theme,
                plan,
                plannedSlots,
                slotResults,
                deadlineAt,
            }),
            "rail diversity pass",
        );
    } catch {
        diversifiedResults = slotResults;
    }

    const slotComponents = diversifiedResults.map((r, i) => ({
        position: plannedSlots[i].position,
        component: r.component,
    }));

    const screen = assembleScreen(slotComponents);
    return {
        components: screen.components,
        canvas_settings: plan.canvas_settings ?? { statusBarVisible: true, statusBarTopSafeArea: true },
    };
}

function buildBaselineTheme(tokens: ScreenTokens): ThemeTokens {
    return {
        accentColor: tokens.accentColor,
        secondaryColor: tokens.accentColor,
        surfaceStyle: tokens.surfaceStyle,
        density: tokens.density,
        fontDesign: tokens.fontDesign,
        cornerRadiusScale: "medium",
        usesGradient: false,
        appName: "Workspace",
        voiceTone: "professional",
        mascotSymbol: "",
        itemNoun: "items",
        ctaVerb: "Open",
        primaryMetricLabel: "Progress",
        primaryMetricUnit: "%",
        sampleItems: ["Priority item:Start here:Open", "Follow up:Keep momentum:In Progress", "Review:End of day:Soon", "Wrap up:Final check:Pending"],
        sampleMetrics: ["Progress:72%:+6%", "Focus:14:+2", "Active:9:+1", "Done:5:+1"],
        sampleRailItems: ["Featured", "Continue", "New", "Popular", "Saved"],
        ctaText: "Continue",
        domainTags: ["productivity"],
        sharedFacts: {
            greeting: "Welcome back",
            userName: "Alex",
            primaryMetricValue: "72%",
            secondaryMetricValue: "14 active",
            streakValue: "5 days",
            progressPercent: 72,
            todayDate: "Mon, Jan 15",
        },
    };
}

function inferFallbackArchetype(prompt: string): ScreenArchetype {
    const p = prompt.toLowerCase();
    if (/\btracker\b|\bcalorie\b|\bhabit\b|\bfitness\b|\bsleep\b/.test(p)) return "tracker";
    if (/\bshop\b|\bstore\b|\bcart\b|\bcheckout\b/.test(p)) return "marketplace";
    if (/\bchat\b|\bmessage\b|\binbox\b/.test(p)) return "chat";
    return "dashboard";
}

function buildEmergencyGeneratedScreen(prompt: string): {
    components: AnyComponent[];
    canvas_settings: CanvasSettings;
    theme: ThemeTokens;
    exemplarsUsed: string[];
} {
    const theme = buildBaselineTheme({ accentColor: "blue:1.0", surfaceStyle: "utility", density: "regular", fontDesign: "default" });
    const archetype = inferFallbackArchetype(prompt);
    const plan = defaultPlanFromArchetype(archetype, theme);
    const fallbackSlots = plan.slots.slice(0, 4);
    const slotComponents = fallbackSlots.map((slot) => ({
        position: slot.position,
        component: buildFallbackSlot(slot, theme),
    }));
    const screen = assembleScreen(slotComponents);
    return {
        components: screen.components,
        canvas_settings: plan.canvas_settings ?? { statusBarVisible: true, statusBarTopSafeArea: true },
        theme,
        exemplarsUsed: [],
    };
}

function assembleScreen(slotComponents: Array<{ position: SlotPosition; component: AnyComponent }>): { components: AnyComponent[] } {
    const top = slotComponents.filter((s) => s.position === "top").map((s) => s.component);
    const body = slotComponents.filter((s) => s.position === "body").map((s) => s.component);
    const bottom = slotComponents.filter((s) => s.position === "bottom").map((s) => s.component);
    const overlay = slotComponents.filter((s) => s.position === "overlay").map((s) => s.component);
    const liftedOverlay = bottom.length > 0
        ? overlay.map((component) => ({
            ...component,
            modifiers: [...(Array.isArray(component.modifiers) ? component.modifiers : []), { type: "Offset", properties: { x: 0, y: -64 } }],
        }))
        : overlay;

    const scrollContent: AnyComponent = {
        type: "VStack",
        properties: { alignment: "leading", spacing: 16 },
        modifiers: [
            { type: "Frame", properties: { widthType: "Full", heightType: "Default" } },
            { type: "Padding", properties: { amount: 16, location: "all" } },
        ],
        children: [...top, ...body],
    };

    const mainColumn: AnyComponent[] = [
        {
            type: "ScrollView",
            properties: { axis: "vertical", showsIndicators: false },
            modifiers: [{ type: "Frame", properties: { widthType: "Full", heightType: "Full" } }],
            children: [scrollContent],
        },
        ...bottom,
    ];

    let root: AnyComponent;
    if (overlay.length > 0) {
        root = {
            type: "ZStack",
            properties: { alignment: "bottomTrailing" },
            modifiers: [{ type: "Frame", properties: { widthType: "Full", heightType: "Full" } }],
            children: [
                {
                    type: "VStack",
                    properties: { alignment: "leading", spacing: 0 },
                    modifiers: [{ type: "Frame", properties: { widthType: "Full", heightType: "Full" } }],
                    children: mainColumn,
                },
                ...liftedOverlay,
            ],
        };
    } else {
        root = {
            type: "VStack",
            properties: { alignment: "leading", spacing: 0 },
            modifiers: [{ type: "Frame", properties: { widthType: "Full", heightType: "Full" } }],
            children: mainColumn,
        };
    }

    return { components: postProcessComponents([root]) };
}

// ─── Selection editing (unchanged from v1) ───────────────────────────────────

function getComponentDepth(component: AnyComponent): number {
    if (!Array.isArray(component.children) || component.children.length === 0) return 1;
    return 1 + Math.max(...component.children.map(getComponentDepth));
}

function buildSelectionSystemPrompt(component: AnyComponent, intent: EditIntent): string {
    const isContainerNode = CONTAINER_TYPES.has(component.type);
    const isText = component.type === "Text";
    const isSymbol = component.type === "SF Symbol";
    const childCount = isContainerNode ? (component.children?.length ?? 0) : 0;

    const focusHints: Record<EditIntent, string> = {
        style: `Focus ONLY on modifiers. Preserve type, properties, and children EXACTLY. Do not rewrite copy.`,
        layout: `Focus ONLY on Frame, Padding, alignment properties. Preserve all other modifiers and all content.`,
        structure: isContainerNode
            ? `You may add or remove children. Preserve all modifiers and properties of the container itself.`
            : `This is a leaf node (${component.type}). It cannot have children. Suggest wrapping instead.`,
        content: isText ? `Update properties.text only. Preserve ALL modifiers exactly.`
            : isSymbol ? `Update properties.symbolName only. Use only valid SF Symbol names.`
                : `Update relevant data properties only. Do not change modifiers or children structure.`,
        wrap: `Return a new container that WRAPS the selected component as a child unchanged inside children[].`,
        canvas: `Return only canvas_settings changes. Output: { "canvas_settings": { ... } }`,
        unknown: `Apply the user's change. Preserve everything not mentioned. Err toward minimal changes.`,
    };

    return `You are a SwiftUI component editor. The user has a component selected.
Return the updated component as JSON. Output shape: {"component": UIComponent}

Infer intent: styling edits → modify modifiers only. Adding/removing children → keep all others.
Never change Text.properties.text unless the user explicitly asks to change the wording.
When changing font, use a single "Font" modifier with fontSize and/or fontWeight.
For color changes use "Foreground Color" with { "color": "colorname:opacity" }.
Clamp numeric fontSize to 8...72. Never return empty text for Text components.
If user gives an explicit numeric font size (e.g. 50), use that exact value (clamped 8...72), as a numeric string.
For style-only requests ("make red", "increase font"), do not alter structure, children, or text copy.

${SCHEMA_RULES}
${CANVAS_SETTINGS_RULES}

--- EDIT CONTEXT ---
SELECTED TYPE: ${component.type}
EDIT INTENT: ${intent}
CONSTRAINT: ${focusHints[intent]}
TREE DEPTH: ${getComponentDepth(component)} levels
CHILDREN COUNT: ${isContainerNode ? childCount : "N/A (leaf node)"}
--- END EDIT CONTEXT ---`;
}

const STYLE_PATCH_SYSTEM_PROMPT = `You are a SwiftUI modifier patcher.
Given the CURRENT modifiers array and a user request, return ONLY the updated modifiers array.
Output shape: { "modifiers": [...] }
- Preserve modifiers not mentioned in the request.
- Use exact modifier type strings from the schema.
- Font: { "type": "Font", "properties": { "fontSize": string, "fontWeight": string } }
- Color: { "type": "Foreground Color", "properties": { "color": "colorname:opacity" } }
- Do NOT add children, change properties, or return the full component.`;

function parseRequestedColor(prompt: string): string | null {
    const p = prompt.toLowerCase();
    const colors = ["primary", "secondary", "tertiary", "quaternary", "red", "blue", "green", "orange", "purple", "yellow", "teal", "pink", "gray", "white", "black", "mint", "indigo", "cyan", "brown"];
    let match: string | null = null;
    for (const color of colors) {
        const re = new RegExp(`\\b${color}\\b`);
        if (re.test(p)) {
            match = color;
            break;
        }
    }
    if (!match) return null;
    const opacityMatch = p.match(/(?:opacity|alpha)\s*(?:to|=|:)?\s*(\d{1,3}(?:\.\d+)?)/);
    if (opacityMatch) {
        const raw = Number(opacityMatch[1]);
        const normalized = raw > 1 ? raw / 100 : raw;
        const opacity = Math.max(0, Math.min(1, normalized));
        return `${match}:${opacity.toFixed(2).replace(/\.?0+$/, "")}`;
    }
    return `${match}:1.0`;
}

function semanticFontSizeToNumber(size: string): number | null {
    const key = size.trim();
    const map: Record<string, number> = {
        largeTitle: 34, title: 28, title2: 22, title3: 20, headline: 17, body: 17, callout: 16,
        subheadline: 15, footnote: 13, caption: 12, caption2: 11,
    };
    if (map[key]) return map[key];
    const n = Number(key);
    return Number.isFinite(n) ? n : null;
}

function parseRequestedFontSize(prompt: string): { target: number; explicit: boolean } | null {
    const p = prompt.toLowerCase();
    const explicit = p.match(/(?:font(?:\s*size)?|text(?:\s*size)?|size)\s*(?:to|=|:)?\s*(\d{1,3})/);
    if (explicit) {
        return { target: Math.max(8, Math.min(72, Number(explicit[1]))), explicit: true };
    }
    const loose = p.match(/\b(\d{1,3})\s*(?:pt|px)?\b/);
    if (loose && /(?:\bfont\b|\bsize\b|\btext\b)/.test(p)) {
        return { target: Math.max(8, Math.min(72, Number(loose[1]))), explicit: true };
    }
    if (/\bbigger\b|\blarger\b|\bincrease\b/.test(p)) {
        return { target: 0, explicit: false };
    }
    return null;
}

function applyDeterministicModifierEdits(component: AnyComponent, prompt: string): AnyComponent | null {
    const p = prompt.toLowerCase();
    const cloned = JSON.parse(JSON.stringify(component)) as AnyComponent;
    if (!Array.isArray(cloned.modifiers)) cloned.modifiers = [];
    const modifiers = [...cloned.modifiers];
    let touched = false;

    const hasAny = (...patterns: string[]) => patterns.some((pattern) => new RegExp(pattern, "i").test(prompt));
    const extractNumber = (...patterns: RegExp[]): number | null => {
        for (const pattern of patterns) {
            const m = p.match(pattern);
            if (!m) continue;
            const v = Number(m[1]);
            if (Number.isFinite(v)) return v;
        }
        return null;
    };
    const parseAxisValue = (axis: "x" | "y"): number | null => {
        const m = p.match(new RegExp(`${axis}\\s*(?:to|=|:)?\\s*(-?\\d+(?:\\.\\d+)?)`));
        if (!m) return null;
        const v = Number(m[1]);
        return Number.isFinite(v) ? v : null;
    };
    const toOpacity = (v: number) => {
        const normalized = v > 1 ? v / 100 : v;
        return Math.max(0, Math.min(1, normalized));
    };
    const parseDimensionType = (axis: "width" | "height"): "Custom" | "Default" | "Full" | null => {
        if (new RegExp(`\\b${axis}\\b.*\\b(full|fill|max)\\b`).test(p)) return "Full";
        if (new RegExp(`\\b${axis}\\b.*\\b(default|auto|intrinsic)\\b`).test(p)) return "Default";
        if (new RegExp(`\\b${axis}\\b.*\\b(custom|fixed)\\b`).test(p)) return "Custom";
        return null;
    };
    const parsePaddingLocation = (): string | null => {
        if (/\bhorizontal\b/.test(p)) return "horizontal";
        if (/\bvertical\b/.test(p)) return "vertical";
        if (/\bleading\b|\bleft\b/.test(p)) return "leading";
        if (/\btrailing\b|\bright\b/.test(p)) return "trailing";
        if (/\btop\b/.test(p)) return "top";
        if (/\bbottom\b/.test(p)) return "bottom";
        if (/\ball\b/.test(p)) return "all";
        return null;
    };
    const parseFontWeight = (): string | null => {
        const weights = ["ultraLight", "thin", "light", "regular", "medium", "semibold", "bold", "heavy", "black"] as const;
        const aliases: Record<string, string> = {
            "ultralight": "ultraLight", "ultra light": "ultraLight",
            "semi bold": "semibold", "semi-bold": "semibold",
        };
        for (const w of weights) {
            if (new RegExp(`\\b${w}\\b`, "i").test(prompt)) return w;
        }
        for (const [k, v] of Object.entries(aliases)) {
            if (new RegExp(`\\b${k}\\b`).test(p)) return v;
        }
        if (/\bbolder\b|\bbolden\b/.test(p)) return "bold";
        if (/\blighter\b/.test(p)) return "light";
        return null;
    };
    const parseFontDesign = (): string | null => {
        if (/\bserif\b/.test(p)) return "serif";
        if (/\brounded\b/.test(p)) return "rounded";
        if (/\bmonospaced\b|\bmono\b/.test(p)) return "monospaced";
        if (/\bdefault\b/.test(p)) return "default";
        return null;
    };
    const parseClipShape = (): string | null => {
        if (/\bcircle\b/.test(p)) return "Circle";
        if (/\bcapsule\b|\bpill\b/.test(p)) return "Capsule";
        if (/\bellipse\b|\boval\b/.test(p)) return "Ellipse";
        if (/\brounded rectangle\b|\broundedrectangle\b/.test(p)) return "RoundedRectangle";
        if (/\brectangle\b/.test(p)) return "Rectangle";
        return null;
    };
    const parseTextAlignment = (): string | null => {
        if (/\bcenter(?:ed)?\b/.test(p)) return "center";
        if (/\btrailing\b|\bright\b/.test(p)) return "trailing";
        if (/\bleading\b|\bleft\b/.test(p)) return "leading";
        return null;
    };
    const parseAspectMode = (): string | null => {
        if (/\bfill\b/.test(p)) return "fill";
        if (/\bfit\b/.test(p)) return "fit";
        return null;
    };
    const makeDefaultModifierChild = (type: "Background" | "Overlay" | "Mask"): AnyComponent => {
        if (type === "Mask") return { type: "Circle", properties: {}, modifiers: [] };
        if (type === "Overlay") return { type: "Text", properties: { text: "Text" }, modifiers: [] };
        return { type: "RoundedRectangle", properties: { cornerRadius: 8 }, modifiers: [] };
    };
    const removeModifier = (type: string) => {
        const before = modifiers.length;
        for (let i = modifiers.length - 1; i >= 0; i--) {
            if (isObject(modifiers[i]) && modifiers[i].type === type) modifiers.splice(i, 1);
        }
        if (modifiers.length !== before) touched = true;
    };
    const upsertModifier = (type: string, nextProps: Record<string, unknown>, merge = true, children?: AnyComponent[]) => {
        const idx = modifiers.findIndex((m) => isObject(m) && m.type === type);
        const current = idx >= 0 && isObject(modifiers[idx].properties)
            ? modifiers[idx].properties as Record<string, unknown>
            : {};
        const updated = merge ? { ...current, ...nextProps } : { ...nextProps };
        const nextMod: Record<string, unknown> = { type, properties: updated };
        if (children) nextMod.children = children;
        if (idx >= 0) modifiers[idx] = nextMod;
        else modifiers.push(nextMod);
        touched = true;
    };

    // Global add/remove modifier directives
    const removeRequested = /\b(remove|delete|clear|strip|disable|turn off|without|no)\b/.test(p);
    const modifierPhraseMap: Array<{ type: string; re: RegExp }> = [
        { type: "Frame", re: /\bframe\b|\bwidth\b|\bheight\b|\bfull width\b|\bfull height\b/ },
        { type: "Padding", re: /\bpadding\b|\bpad\b|\binset\b/ },
        { type: "Background Color", re: /\bbackground color\b|\bbg color\b/ },
        { type: "Foreground Color", re: /\bforeground color\b|\btext color\b|\btint\b/ },
        { type: "Font", re: /\bfont\b|\bweight\b|\btext size\b/ },
        { type: "Corner Radius", re: /\bcorner radius\b|\brounded\b/ },
        { type: "Shadow", re: /\bshadow\b/ },
        { type: "Opacity", re: /\bopacity\b|\balpha\b|\btransparent\b/ },
        { type: "Border", re: /\bborder\b/ },
        { type: "Stroke", re: /\bstroke\b|\boutline\b/ },
        { type: "Background", re: /\bbackground layer\b|\bbackground element\b/ },
        { type: "Overlay", re: /\boverlay\b/ },
        { type: "Mask", re: /\bmask\b/ },
        { type: "Blur", re: /\bblur\b/ },
        { type: "Scale", re: /\bscale\b|\bsize up\b|\bsize down\b/ },
        { type: "Rotation", re: /\brotate\b|\brotation\b|\bangle\b/ },
        { type: "Offset", re: /\boffset\b|\bmove\b|\bshift\b|\bnudge\b/ },
        { type: "Fill", re: /\bfill\b/ },
        { type: "Clipped", re: /\bclip(ped)?\b/ },
        { type: "Clip Shape", re: /\bclip shape\b/ },
        { type: "Text Alignment", re: /\balign(?:ment)?\b/ },
        { type: "Aspect Ratio", re: /\baspect\b/ },
        { type: "Z Index", re: /\bz[- ]?index\b|\blayer\b/ },
        { type: "Glass Effect", re: /\bglass\b|\bliquid\b|\bfrost(ed)?\b/ },
    ];
    if (removeRequested) {
        for (const item of modifierPhraseMap) {
            if (item.re.test(p)) removeModifier(item.type);
        }
    }

    // Color + font edits
    const requestedColor = parseRequestedColor(prompt);
    if (requestedColor && (hasAny("\\bcolor\\b", "\\bforeground\\b", "\\btint\\b", "\\btext color\\b") || component.type === "Text" || component.type === "SF Symbol")) {
        upsertModifier("Foreground Color", { color: requestedColor });
    }
    if (requestedColor && hasAny("\\bbackground\\b", "\\bbg\\b")) {
        upsertModifier("Background Color", { color: requestedColor });
    }
    if (requestedColor && hasAny("\\bfill\\b")) {
        upsertModifier("Fill", { color: requestedColor });
    }

    const supportsFont = component.type === "Text" || component.type === "SF Symbol";
    const fontRequest = parseRequestedFontSize(prompt);
    const fontWeight = parseFontWeight();
    const fontDesign = parseFontDesign();
    if (supportsFont && (fontRequest || fontWeight || fontDesign)) {
        const fontIndex = modifiers.findIndex((m) => isObject(m) && m.type === "Font");
        const currentProps = fontIndex >= 0 && isObject(modifiers[fontIndex].properties)
            ? modifiers[fontIndex].properties as Record<string, unknown>
            : {};
        const currentNumeric = typeof currentProps.fontSize === "string"
            ? semanticFontSizeToNumber(currentProps.fontSize)
            : null;
        const computedSize = fontRequest
            ? (fontRequest.explicit ? fontRequest.target : Math.max(12, Math.min(72, (currentNumeric ?? 17) + 8)))
            : undefined;
        const updatedFont: Record<string, unknown> = {
            ...currentProps,
            ...(computedSize !== undefined ? { fontSize: String(computedSize) } : {}),
            ...(fontWeight ? { fontWeight } : {}),
            ...(fontDesign ? { fontDesign } : {}),
        };
        if (!updatedFont.fontWeight) updatedFont.fontWeight = "regular";
        upsertModifier("Font", updatedFont, false);
    }

    // Frame
    const width = extractNumber(/\bwidth\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/, /\bw\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/);
    const height = extractNumber(/\bheight\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/, /\bh\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/);
    const widthType = parseDimensionType("width");
    const heightType = parseDimensionType("height");
    if (width !== null || height !== null || widthType || heightType) {
        const frameProps: Record<string, unknown> = {};
        if (width !== null) {
            frameProps.widthType = "Custom";
            frameProps.width = Math.max(0, width);
        }
        if (height !== null) {
            frameProps.heightType = "Custom";
            frameProps.height = Math.max(0, height);
        }
        if (widthType) frameProps.widthType = widthType;
        if (heightType) frameProps.heightType = heightType;
        upsertModifier("Frame", frameProps);
    }

    // Padding
    const padAmount = extractNumber(/\bpadding\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/, /\bpad\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/, /\binset\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/);
    const padLocation = parsePaddingLocation();
    if (padAmount !== null || /\bpadding\b|\bpad\b|\binset\b/.test(p)) {
        upsertModifier("Padding", {
            ...(padAmount !== null ? { amount: Math.max(0, padAmount) } : {}),
            ...(padLocation ? { location: padLocation } : {}),
        });
    }

    // Corner radius
    const radius = extractNumber(/\bcorner radius\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/, /\bradius\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/, /\bround(?:ed)?\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/);
    if (radius !== null) upsertModifier("Corner Radius", { radius: Math.max(0, radius) });

    // Shadow
    if (/\bshadow\b/.test(p)) {
        const shadowRadius = extractNumber(/\bshadow(?:\s+radius)?\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/, /\bradius\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/);
        const shadowX = parseAxisValue("x");
        const shadowY = parseAxisValue("y");
        const shadowColor = parseRequestedColor(prompt);
        const shadowOpacityRaw = extractNumber(/(?:shadow\s+)?(?:opacity|alpha)\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/);
        upsertModifier("Shadow", {
            ...(shadowRadius !== null ? { radius: Math.max(0, shadowRadius) } : {}),
            ...(shadowX !== null ? { x: shadowX } : {}),
            ...(shadowY !== null ? { y: shadowY } : {}),
            ...(shadowColor ? { color: shadowColor } : {}),
            ...(shadowOpacityRaw !== null ? { opacity: toOpacity(shadowOpacityRaw) } : {}),
        });
    }

    // Opacity
    const opacityRaw = extractNumber(/\bopacity\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/, /\balpha\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/, /\b(\d{1,3})%\s*opaque\b/);
    if (opacityRaw !== null) upsertModifier("Opacity", { opacity: toOpacity(opacityRaw) });

    // Border / Stroke
    const lineWidth = extractNumber(/\bline\s*width\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/, /\bborder\s*width\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/, /\bstroke\s*width\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/);
    const borderColor = parseRequestedColor(prompt);
    if (/\bborder\b/.test(p)) {
        upsertModifier("Border", {
            ...(lineWidth !== null ? { width: Math.max(0, lineWidth) } : {}),
            ...(borderColor ? { color: borderColor } : {}),
        });
    }
    if (/\bstroke\b|\boutline\b/.test(p)) {
        upsertModifier("Stroke", {
            ...(lineWidth !== null ? { lineWidth: Math.max(0, lineWidth) } : {}),
            ...(borderColor ? { color: borderColor } : {}),
        });
    }

    // Blur
    const blur = extractNumber(/\bblur(?:\s+radius)?\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/);
    if (blur !== null || /\bblur\b/.test(p)) upsertModifier("Blur", { radius: Math.max(0, blur ?? 8) });

    // Scale
    const scaleUniform = extractNumber(/\bscale\s*(?:to|=|:)?\s*(-?\d+(?:\.\d+)?)/, /\bzoom\s*(?:to|=|:)?\s*(-?\d+(?:\.\d+)?)/);
    const scaleX = extractNumber(/\bscale\s*x\s*(?:to|=|:)?\s*(-?\d+(?:\.\d+)?)/, /\bx\s*scale\s*(?:to|=|:)?\s*(-?\d+(?:\.\d+)?)/);
    const scaleY = extractNumber(/\bscale\s*y\s*(?:to|=|:)?\s*(-?\d+(?:\.\d+)?)/, /\by\s*scale\s*(?:to|=|:)?\s*(-?\d+(?:\.\d+)?)/);
    if (scaleUniform !== null || scaleX !== null || scaleY !== null) {
        upsertModifier("Scale", {
            ...(scaleUniform !== null ? { x: scaleUniform, y: scaleUniform } : {}),
            ...(scaleX !== null ? { x: scaleX } : {}),
            ...(scaleY !== null ? { y: scaleY } : {}),
        });
    }

    // Rotation
    const angle = extractNumber(/\b(?:rotate|rotation|angle)\s*(?:to|=|:)?\s*(-?\d+(?:\.\d+)?)/);
    if (angle !== null || /\brotate\b/.test(p)) upsertModifier("Rotation", { angle: angle ?? 15 });

    // Offset
    const offsetX = parseAxisValue("x");
    const offsetY = parseAxisValue("y");
    if (/\boffset\b|\bmove\b|\bshift\b|\bnudge\b/.test(p) || offsetX !== null || offsetY !== null) {
        upsertModifier("Offset", {
            ...(offsetX !== null ? { x: offsetX } : {}),
            ...(offsetY !== null ? { y: offsetY } : {}),
        });
    }

    // Clipped / Clip shape
    if (/\bclip(ped)?\b/.test(p) && !/\bclip shape\b/.test(p)) {
        if (removeRequested) removeModifier("Clipped");
        else upsertModifier("Clipped", {});
    }
    const clipShape = parseClipShape();
    if (/\bclip shape\b|\bmask shape\b/.test(p) || clipShape) {
        if (removeRequested && (/\bclip shape\b|\bmask shape\b/.test(p))) {
            removeModifier("Clip Shape");
        } else {
            upsertModifier("Clip Shape", { shape: clipShape ?? "Rectangle" });
        }
    }

    // Text alignment
    const textAlignment = parseTextAlignment();
    if (textAlignment && (/\balign(?:ment)?\b/.test(p) || /\btext\b/.test(p))) {
        upsertModifier("Text Alignment", { alignment: textAlignment });
    }

    // Aspect ratio
    const ratio = extractNumber(/\bratio\s*(?:to|=|:)?\s*(\d+(?:\.\d+)?)/);
    const aspectMode = parseAspectMode();
    if (/\baspect\b/.test(p) || ratio !== null || aspectMode) {
        upsertModifier("Aspect Ratio", {
            ...(ratio !== null ? { ratio } : {}),
            ...(aspectMode ? { aspectRatio: aspectMode, contentMode: aspectMode } : {}),
        });
    }

    // Z Index
    const zIndex = extractNumber(/\bz[- ]?index\s*(?:to|=|:)?\s*(-?\d+(?:\.\d+)?)/, /\blayer\s*(?:to|=|:)?\s*(-?\d+(?:\.\d+)?)/);
    if (zIndex !== null) upsertModifier("Z Index", { index: zIndex });

    // Background / Overlay / Mask structural modifiers
    if (/\boverlay\b/.test(p) && !removeRequested) upsertModifier("Overlay", {}, true, [makeDefaultModifierChild("Overlay")]);
    if (/\bbackground\b/.test(p) && /\blayer\b|\belement\b/.test(p) && !removeRequested) {
        upsertModifier("Background", {}, true, [makeDefaultModifierChild("Background")]);
    }
    if (/\bmask\b/.test(p) && !removeRequested) upsertModifier("Mask", {}, true, [makeDefaultModifierChild("Mask")]);

    // Glass effect
    if (/\bglass\b|\bliquid\b|\bfrost(ed)?\b/.test(p)) {
        if (removeRequested) removeModifier("Glass Effect");
        else upsertModifier("Glass Effect", {});
    }

    if (!touched) return null;
    cloned.modifiers = modifiers;
    return cloned;
}

async function applyStylePatch(component: AnyComponent, prompt: string): Promise<AnyComponent | null> {
    const response = await callOpenAI({
        model: SELECTION_MODEL,
        messages: [
            { role: "system", content: STYLE_PATCH_SYSTEM_PROMPT },
            { role: "system", content: `CURRENT MODIFIERS:\n${JSON.stringify(component.modifiers ?? [])}` },
            { role: "user", content: prompt },
        ],
        temperature: 0, maxTokens: STYLE_PATCH_MAX_TOKENS, responseFormat: { type: "json_object" },
    });
    if (!response.ok) return null;
    const parsed = parseJsonSafe(response.content);
    if (isJsonParseError(parsed) || !isObject(parsed.value)) return null;
    const result = parsed.value as Record<string, unknown>;
    if (!Array.isArray(result.modifiers)) return null;
    return { ...component, modifiers: result.modifiers as Array<Record<string, unknown>> };
}

// ─── Repair ──────────────────────────────────────────────────────────────────

function cheapRepair(component: AnyComponent): { component: AnyComponent; issues: string[] } {
    const issues: string[] = [];
    const visit = (node: AnyComponent): AnyComponent => {
        if (node.type === "Button" && (!Array.isArray(node.children) || node.children.length === 0)) {
            node.children = [{ type: "Text", properties: { text: "Button" }, modifiers: [{ type: "Font", properties: { fontSize: "body", fontWeight: "semibold" } }] }];
            issues.push("Added missing Button child");
        }
        if (node.type === "ScrollView") {
            if (!Array.isArray(node.children) || node.children.length === 0) {
                node.children = [{ type: "VStack", properties: { alignment: "leading", spacing: 16 }, modifiers: [], children: [] }];
                issues.push("Added missing ScrollView child");
            } else if (node.children.length > 1) {
                node.children = [{ type: "VStack", properties: { alignment: "leading", spacing: 16 }, modifiers: [], children: node.children }];
                issues.push("Wrapped multiple ScrollView children");
            }
        }
        if (node.type === "Text") {
            const props = isObject(node.properties) ? node.properties : {};
            if (typeof props.text !== "string" || props.text.trim() === "") {
                props.text = "Text";
                node.properties = props;
                issues.push("Fixed empty Text");
            }
        }
        if (Array.isArray(node.modifiers)) {
            const hasCornerRadius = node.modifiers.some((m) => (m as Record<string, unknown>).type === "Corner Radius");
            if (hasCornerRadius) {
                node.modifiers = node.modifiers.map((m) => {
                    const mod = m as Record<string, unknown>;
                    return mod.type === "Border" ? { ...mod, type: "Stroke" } : mod;
                });
            }
        }
        if (Array.isArray(node.children)) node.children = node.children.map(visit);
        return node;
    };
    return { component: visit(component), issues };
}

const REPAIR_SYSTEM_PROMPT = `Fix schema errors in the SwiftUI JSON. Output ONLY the corrected JSON: { "component": <UIComponent> }
CONTAINERS (must have children[]): VStack, HStack, ZStack, ScrollView, Button
LEAVES (delete children if present): Text, Image, SF Symbol, Shape, Chart, Spacer, Divider, Rectangle, Circle, RoundedRectangle, Capsule, Ellipse, Linear Gradient, Text Field, Switch, Slider, Progress View, Status Bar, Gauge
Invalid type: row/cell->HStack | card/stat->VStack | label/title->Text | icon->SF Symbol | graph->Chart | progress/progressbar->Progress View
Invalid modifier: remove it. Button with Background Color on label: buttonStyle="plain"
Shape color rule: Background Color on shape -> convert to Fill. Text.properties.text must be non-empty. Fix ALL errors.
Border vs Stroke rule: if a node has a Corner Radius modifier, convert any "Border" modifier to "Stroke" (keep same properties).
Color format: always "colorname:opacity" e.g. "blue:1.0", "gray:0.12"`;

async function compileWithRepairMessages(params: {
    messages: Array<Record<string, unknown>>;
    maxAttempts: number;
    model?: string;
    maxTokens?: number;
    repairModel?: string;
    repairMaxTokens?: number;
}) {
    let lastError = "";
    let lastContent = "";
    let attempt = 0;

    while (attempt < params.maxAttempts) {
        const isFirst = attempt === 0;
        const messages = isFirst ? params.messages : [
            { role: "system", content: REPAIR_SYSTEM_PROMPT },
            { role: "user", content: `Previous JSON:\n${lastContent}\n\nErrors:\n${lastError}` },
        ];

        const response = await callOpenAI({
            model: isFirst ? (params.model ?? SELECTION_MODEL) : (params.repairModel ?? REPAIR_MODEL),
            messages, temperature: 0,
            maxTokens: isFirst ? (params.maxTokens ?? SELECTION_MAX_TOKENS) : (params.repairMaxTokens ?? REPAIR_MAX_TOKENS),
            responseFormat: { type: "json_object" },
        });

        if (!response.ok) return { ok: false as const, error: response.error };
        lastContent = response.content;
        const parsed = parseJsonSafe(response.content);
        if (isJsonParseError(parsed)) { lastError = parsed.error; attempt++; continue; }
        if (!isObject(parsed.value)) { lastError = "Response is not an object"; attempt++; continue; }

        const result = parsed.value as Record<string, unknown>;
        const raw = result.component ?? (Array.isArray(result.components) ? result.components[0] : null);

        if (!raw && isObject(result.canvas_settings)) {
            return { ok: true as const, parsed: { mode: "canvas", canvas_settings: result.canvas_settings } };
        }
        if (!isObject(raw)) { lastError = "Missing component in response"; attempt++; continue; }

        const { component: cheapFixed } = cheapRepair(raw as AnyComponent);
        const fixed = postProcessComponents([cheapFixed])[0];
        if (!VALID_COMPONENT_TYPES.has(fixed.type)) { lastError = `Invalid component type: ${fixed.type}`; attempt++; continue; }
        return { ok: true as const, parsed: { mode: "component", component: fixed, canvas_settings: result.canvas_settings } };
    }
    return { ok: false as const, error: `Failed after ${params.maxAttempts} attempts: ${lastError}` };
}

// ─── Post-processing (unchanged from v1) ─────────────────────────────────────

function postProcessComponents(components: AnyComponent[]): AnyComponent[] {
    const cloned = JSON.parse(JSON.stringify(components)) as AnyComponent[];
    const CONTAINER_PP = new Set(["VStack", "HStack", "ZStack", "ScrollView", "Button"]);
    const LEAF_PP = new Set(["Text", "Image", "SF Symbol", "Shape", "Chart", "Spacer", "Divider", "Rectangle", "Circle", "RoundedRectangle", "Capsule", "Ellipse", "Linear Gradient", "Text Field", "Switch", "Slider", "Progress View", "Status Bar", "Gauge"]);
    const SHAPE_PP = new Set(["Shape", "Rectangle", "Circle", "RoundedRectangle", "Capsule", "Ellipse"]);
    const ALL_VALID_PP = new Set([...CONTAINER_PP, ...LEAF_PP]);

    const coerceType = (type: unknown): string => {
        if (typeof type === "string" && ALL_VALID_PP.has(type)) return type;
        if (typeof type === "string") {
            const t = type.toLowerCase();
            if (t.includes("gradient")) return "Linear Gradient";
            if (t === "progress" || t === "progressview" || t === "progress view" || t === "progressbar" || t === "progress bar") return "Progress View";
        }
        return "Text";
    };

    const normalizeSFSymbolName = (raw: string): string => {
        let name = raw.trim().toLowerCase();
        if (!name) return "questionmark";
        const aliasMap: Record<string, string> = {
            "plane": "airplane", "airplane": "airplane", "paper plane": "paperplane", "paperplane": "paperplane",
            "send": "paperplane", "delete": "trash", "trash": "trash", "remove": "trash", "bin": "trash",
            "close": "xmark", "x": "xmark", "add": "plus", "plus": "plus", "edit": "pencil", "pencil": "pencil",
            "search": "magnifyingglass", "settings": "gearshape", "gear": "gearshape", "share": "square.and.arrow.up",
            "heart": "heart", "like": "heart", "star": "star", "user": "person", "profile": "person",
            "lock": "lock", "unlock": "lock.open", "camera": "camera", "photo": "photo", "image": "photo",
            "play": "play.fill", "pause": "pause.fill", "stop": "stop.fill", "menu": "line.3.horizontal",
            "more": "ellipsis", "info": "info.circle", "warning": "exclamationmark.triangle",
            "alert": "exclamationmark.triangle", "check": "checkmark", "success": "checkmark.circle",
            "error": "xmark.circle", "back": "chevron.left", "forward": "chevron.right",
            "up": "chevron.up", "down": "chevron.down",
        };
        if (aliasMap[name]) return aliasMap[name];
        name = name.replace(/\s+/g, ".").replace(/_+/g, ".");
        if (aliasMap[name]) return aliasMap[name];
        if (!/^[a-z0-9.]+$/.test(name)) return "questionmark";
        return name;
    };

    const normalizeModifierType = (rawType: unknown): string => {
        if (typeof rawType !== "string") return "Font";
        const key = rawType.toLowerCase().replace(/[^a-z]/g, "");
        const aliases: Record<string, string> = {
            frame: "Frame", padding: "Padding", backgroundcolor: "Background Color", bgcolor: "Background Color",
            background: "Background", foregroundcolor: "Foreground Color", textcolor: "Foreground Color",
            fontcolor: "Foreground Color", foreground: "Foreground Color", font: "Font",
            cornerradius: "Corner Radius", clipped: "Clipped", shadow: "Shadow", opacity: "Opacity",
            rotation: "Rotation", rotate: "Rotation", scale: "Scale", offset: "Offset",
            clipshape: "Clip Shape", mask: "Mask", blur: "Blur", overlay: "Overlay",
            border: "Border", stroke: "Stroke", textalignment: "Text Alignment",
            fill: "Fill", aspectratio: "Aspect Ratio", zindex: "Z Index", glasseffect: "Glass Effect",
        };
        return aliases[key] ?? rawType;
    };

    const readFontValue = (props: Record<string, unknown>, keys: string[]): string | undefined => {
        for (const key of keys) { const v = props[key]; if (typeof v === "string" && v.length > 0) return v; }
        return undefined;
    };

    const visit = (node: AnyComponent): AnyComponent => {
        if (!node || typeof node !== "object") return { type: "Text", properties: { text: "" }, modifiers: [] };

        const inferredType = typeof node.type === "string" ? node.type
            : (Array.isArray(node.children) && node.children.length > 0 ? "VStack"
                : node.properties?.text != null ? "Text" : "Text");
        node.type = coerceType(inferredType);
        if (!isObject(node.properties)) node.properties = {};
        if (!Array.isArray(node.modifiers)) node.modifiers = [];

        if (CONTAINER_PP.has(node.type)) {
            node.children = Array.isArray(node.children) ? node.children.map(visit) : [];
        } else {
            delete node.children;
        }

        if (node.type === "Text") {
            const props = node.properties as Record<string, unknown>;
            const tv = typeof props.text === "string" ? props.text.trim() : "";
            const cleaned = tv.length > 0 ? sanitizeInstructionalDisplayText(tv) : "";
            props.text = cleaned.length > 0 ? cleaned : "Text";
        }
        if (node.type === "SF Symbol") {
            const props = node.properties as Record<string, unknown>;
            props.symbolName = typeof props.symbolName === "string" ? normalizeSFSymbolName(props.symbolName) : "questionmark";
        }

        node.modifiers = node.modifiers.map((mod) => {
            let modValue: unknown = mod;
            if (typeof modValue === "string") {
                const raw = modValue;
                modValue = { type: raw.includes(":") ? raw.split(":")[0].trim() : raw.trim(), properties: {} };
            } else if (!isObject(modValue)) {
                modValue = { type: "Font", properties: {} };
            }
            let modObj = modValue as Record<string, unknown>;
            if (!isObject(modObj.properties)) modObj.properties = {};
            modObj.type = normalizeModifierType(modObj.type);

            if (modObj.type === "fontSize" || modObj.type === "fontWeight") {
                const fp = modObj.properties as Record<string, unknown>;
                const cf: Record<string, unknown> = { type: "Font", properties: {} };
                const cfp = cf.properties as Record<string, unknown>;
                if (modObj.type === "fontSize") { const sv = readFontValue(fp, ["value", "fontSize", "size"]); if (sv) cfp.fontSize = sv; }
                if (modObj.type === "fontWeight") { const wv = readFontValue(fp, ["value", "fontWeight", "weight"]); if (wv) cfp.fontWeight = wv; }
                modObj = cf;
            }

            if (modObj.type === "Font") {
                const props = modObj.properties as Record<string, unknown>;
                if (props.fontWeight === undefined) { const w = readFontValue(props, ["weight"]); if (w) props.fontWeight = w; }
                if (props.fontSize === undefined) { const s = readFontValue(props, ["size"]); if (s) props.fontSize = s; }
                if (props.fontDesign === undefined) { const d = readFontValue(props, ["design", "fontDesign"]); if (d) props.fontDesign = d; }
                const weightMap: Record<string, string> = { ultralight: "ultraLight", "ultra-light": "ultraLight", thin: "thin", light: "light", regular: "regular", normal: "regular", medium: "medium", semibold: "semibold", "semi-bold": "semibold", "semi bold": "semibold", bold: "bold", heavy: "heavy", black: "black" };
                const rw = typeof props.fontWeight === "string" ? props.fontWeight.toLowerCase() : "";
                if (rw) props.fontWeight = weightMap[rw] ?? props.fontWeight;
                const sizeMap: Record<string, string> = { largetitle: "largeTitle", "large title": "largeTitle", title: "title", title2: "title2", headline: "headline", body: "body", callout: "callout", subheadline: "subheadline", footnote: "footnote", caption: "caption" };
                const rs = typeof props.fontSize === "string" ? props.fontSize.toLowerCase() : "";
                if (rs) props.fontSize = sizeMap[rs] ?? props.fontSize;
                if (typeof props.fontSize === "string") { const n = Number.parseFloat(props.fontSize); if (Number.isFinite(n)) props.fontSize = String(Math.max(8, Math.min(72, n))); }
                const allowedDesigns = new Set(["default", "serif", "rounded", "monospaced"]);
                const rd = typeof props.fontDesign === "string" ? props.fontDesign.toLowerCase() : "";
                if (rd) { if (allowedDesigns.has(rd)) props.fontDesign = rd; else delete props.fontDesign; }
            }

            if (["Background", "Overlay", "Mask"].includes(modObj.type as string)) {
                if (Array.isArray(modObj.children) && modObj.children.length > 0) {
                    modObj.children = (modObj.children as AnyComponent[]).map(visit);
                } else {
                    const defaultChild: AnyComponent = modObj.type === "Mask" ? { type: "Circle", properties: {}, modifiers: [] }
                        : modObj.type === "Overlay" ? { type: "Text", properties: { text: "Text" }, modifiers: [] }
                            : { type: "RoundedRectangle", properties: { cornerRadius: 8 }, modifiers: [] };
                    modObj.children = [visit(defaultChild)];
                }
            }

            if (["Foreground Color", "Background Color", "Fill", "Stroke"].includes(modObj.type as string)) {
                const props = modObj.properties as Record<string, unknown>;
                if (typeof props.color !== "string" || props.color.length === 0) {
                    const ac = (typeof props.value === "string" && props.value) || (typeof props.foregroundColor === "string" && props.foregroundColor) || (typeof props.backgroundColor === "string" && props.backgroundColor) || (typeof props.textColor === "string" && props.textColor) || (typeof props.fillColor === "string" && props.fillColor) || (typeof props.strokeColor === "string" && props.strokeColor) || (typeof props.tint === "string" && props.tint) || undefined;
                    if (ac) props.color = ac;
                }
                if (typeof props.color === "string" && props.color.length > 0 && !props.color.includes(":")) {
                    const ov = props.opacity;
                    if (typeof ov === "number" && Number.isFinite(ov)) props.color = `${props.color}:${Math.max(0, Math.min(1, ov))}`;
                }
            }
            return modObj;
        }).filter((mod) => VALID_MODIFIER_TYPES.has(mod.type as string));

        node.modifiers = node.modifiers.filter((mod) => {
            if ((mod.type as string) !== "Foreground Color") return true;
            const props = isObject(mod.properties) ? mod.properties : {};
            const color = typeof props.color === "string" ? props.color.toLowerCase() : "";
            return color !== "primary" && color !== "primary:1" && color !== "primary:1.0";
        });

        if (SHAPE_PP.has(node.type)) {
            const hasFill = node.modifiers.some((mod) => (mod.type as string) === "Fill");
            node.modifiers = node.modifiers.flatMap((mod) => {
                if ((mod.type as string) !== "Background Color") return [mod];
                if (hasFill) return [];
                return [{ ...mod, type: "Fill" }];
            });
        }

        const hasCornerRadius = node.modifiers.some((mod) => (mod.type as string) === "Corner Radius");
        if (hasCornerRadius) {
            node.modifiers = node.modifiers.map((mod) => {
                if ((mod.type as string) !== "Border") return mod;
                return { ...mod, type: "Stroke" };
            });
        }

        node.modifiers = node.modifiers
            .map((mod, index) => ({ mod, index }))
            .sort((a, b) => {
                const ao = MODIFIER_SORT_INDEX.get(String(a.mod.type ?? "")) ?? Number.MAX_SAFE_INTEGER;
                const bo = MODIFIER_SORT_INDEX.get(String(b.mod.type ?? "")) ?? Number.MAX_SAFE_INTEGER;
                return ao !== bo ? ao - bo : a.index - b.index;
            })
            .map(({ mod }) => mod);

        const modifierChildren: AnyComponent[] = [];
        node.modifiers.forEach((mod) => {
            const type = mod.type as string;
            if (!["Background", "Overlay", "Mask"].includes(type)) return;
            const children = Array.isArray(mod.children) ? (mod.children as AnyComponent[]) : [];
            if (children.length === 0) return;
            const rawId = (mod as Record<string, unknown>).id;
            const modId: string = typeof rawId === "string" ? rawId : crypto.randomUUID();
            if (typeof rawId !== "string") (mod as Record<string, unknown>).id = modId;
            modifierChildren.push({ type: "VStack", properties: {}, modifiers: [], children: children.map(visit), modifierId: modId, modifierType: type });
        });

        const existingChildren = Array.isArray(node.children) ? node.children : [];
        const nonModifierChildren = existingChildren.filter((child) => {
            if (!isObject(child)) return true;
            const c = child as Record<string, unknown>;
            return !(typeof c.modifierId === "string" && typeof c.modifierType === "string" && ["Background", "Overlay", "Mask"].includes(c.modifierType));
        });
        if (modifierChildren.length > 0) {
            node.children = [...nonModifierChildren, ...modifierChildren];
        } else if (nonModifierChildren.length !== existingChildren.length) {
            node.children = nonModifierChildren;
        }
        return node;
    };

    return cloned.map(visit);
}

// ─── OpenAI client ───────────────────────────────────────────────────────────

async function callOpenAI(params: {
    model: string;
    messages: Array<Record<string, unknown>>;
    temperature: number;
    maxTokens?: number;
    responseFormat?: { type: "json_object" };
    timeoutMs?: number;
}) {
    const controller = new AbortController();
    const timeoutMs = params.timeoutMs ?? OPENAI_TIMEOUT_MS;
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    let response: Response;
    try {
        response = await fetch("https://api.openai.com/v1/chat/completions", {
            method: "POST",
            headers: { "Content-Type": "application/json", Authorization: `Bearer ${openaiApiKey}` },
            body: JSON.stringify({ model: params.model, messages: params.messages, temperature: params.temperature, max_tokens: params.maxTokens, response_format: params.responseFormat ?? { type: "json_object" } }),
            signal: controller.signal,
        });
    } catch (err) {
        clearTimeout(timer);
        const msg = err instanceof Error ? err.message : String(err);
        return { ok: false as const, error: msg.toLowerCase().includes("abort") ? `OpenAI request timed out after ${timeoutMs}ms` : `OpenAI network error: ${msg}` };
    }
    clearTimeout(timer);
    if (!response.ok) return { ok: false as const, error: await response.text() };
    let data: any;
    try { data = await response.json(); } catch (err) { return { ok: false as const, error: `OpenAI JSON decode error: ${err instanceof Error ? err.message : String(err)}` }; }
    const content = data?.choices?.[0]?.message?.content;
    if (!content || typeof content !== "string") return { ok: false as const, error: "OpenAI returned empty content" };
    return { ok: true as const, content };
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

type JsonParseResult = { ok: true; value: unknown } | { ok: false; error: string };
function parseJsonSafe(content: string): JsonParseResult {
    try { return { ok: true, value: JSON.parse(content) }; }
    catch (err) { return { ok: false, error: `Invalid JSON: ${err instanceof Error ? err.message : String(err)}` }; }
}
function isJsonParseError(r: JsonParseResult): r is { ok: false; error: string } { return r.ok === false; }
function isObject(v: unknown): v is Record<string, unknown> { return Boolean(v) && typeof v === "object" && !Array.isArray(v); }
function asString(v: unknown, fallback = ""): string { return typeof v === "string" ? v.trim() || fallback : fallback; }
function normalizeSurfaceStyle(v: unknown, fallback: SurfaceStyle = "utility"): SurfaceStyle {
    if (v === "minimal" || v === "editorial" || v === "utility" || v === "immersive" || v === "calm") return v;
    return fallback;
}
function normalizeDensity(v: unknown, fallback: Density = "regular"): Density {
    if (v === "compact" || v === "regular" || v === "airy") return v;
    return fallback;
}
function normalizeSelectedComponent(value: unknown): Record<string, unknown> | null {
    if (typeof value === "string" && value.trim().length > 0) {
        const p = parseJsonSafe(value);
        if (!isJsonParseError(p)) return normalizeSelectedComponent(p.value);
        return null;
    }
    if (!isObject(value)) return null;
    if (isObject(value.component)) return value.component;
    return value;
}

// ─── Request handler ─────────────────────────────────────────────────────────

serve(async (req) => {
    if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

    try {
        if (!supabaseUrl || !supabaseServiceKey) {
            return new Response(JSON.stringify({ error: "Supabase server configuration missing" }), { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } });
        }
        const jwt = (req.headers.get("Authorization") ?? "").replace("Bearer ", "");
        if (!jwt) return new Response(JSON.stringify({ error: "Missing Authorization token" }), { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } });

        const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey);
        const { data: userData, error: userError } = await supabaseAdmin.auth.getUser(jwt);
        if (userError || !userData?.user) return new Response(JSON.stringify({ error: "Unauthorized" }), { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } });

        const userId = userData.user.id;
        let isSubscribed = false;
        try {
            const { data: profile } = await supabaseAdmin.from("profiles").select("is_subscribed, is_premium").eq("id", userId).maybeSingle();
            isSubscribed = Boolean(profile?.is_subscribed || profile?.is_premium);
        } catch (_) { isSubscribed = false; }

        const dailyLimit = isSubscribed ? PRO_DAILY_LIMIT : FREE_DAILY_LIMIT;
        const now = new Date();
        const day = now.toISOString().slice(0, 10);
        const { data: usage } = await supabaseAdmin.from("ai_usage").select("count,last_request_at").eq("user_id", userId).eq("day", day).maybeSingle();
        const currentCount = usage?.count ?? 0;

        const { prompt, selected_component, context } = await req.json();
        const safePrompt = typeof prompt === "string" ? prompt : "";

        const makeReset = () => new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1)).toISOString();
        const makeQuota = (count: number) => ({ remaining: Math.max(0, dailyLimit - count), limit: dailyLimit, reset: makeReset(), rate_limit_seconds: RATE_LIMIT_SECONDS });

        if (safePrompt.trim().toLowerCase() === "quota check" && !selected_component) {
            return new Response(JSON.stringify({ quota: makeQuota(currentCount) }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
        }

        const lastRequestAt = usage?.last_request_at ? new Date(usage.last_request_at) : null;
        if (lastRequestAt) {
            const ss = (now.getTime() - lastRequestAt.getTime()) / 1000;
            if (ss < RATE_LIMIT_SECONDS) {
                return new Response(JSON.stringify({ error: `Rate limit: 1 request every ${RATE_LIMIT_SECONDS}s`, retry_after: Math.ceil(RATE_LIMIT_SECONDS - ss), quota: makeQuota(currentCount) }), { status: 429, headers: { ...corsHeaders, "Content-Type": "application/json" } });
            }
        }

        if (currentCount >= dailyLimit) {
            return new Response(JSON.stringify({ error: "Daily AI limit reached", quota: makeQuota(currentCount) }), { status: 429, headers: { ...corsHeaders, "Content-Type": "application/json" } });
        }

        let resolvedSelection = normalizeSelectedComponent(selected_component);
        if (!resolvedSelection && isObject(context)) resolvedSelection = normalizeSelectedComponent((context as Record<string, unknown>).selected_component_json);
        const forceFullCanvas = isFullCanvasPrompt(safePrompt);
        const hasSelection = (resolvedSelection !== null && resolvedSelection !== undefined) && !forceFullCanvas;
        const selectedComponentType = isObject(resolvedSelection) && typeof resolvedSelection.type === "string"
            ? String(resolvedSelection.type)
            : null;

        // Best-effort prompt logging (no behavior impact if logging fails).
        const promptForLog = safePrompt.trim();
        if (promptForLog.length > 0) {
            try {
                await supabaseAdmin.from("ai_prompts").insert({
                    user_id: userId,
                    prompt: promptForLog,
                    prompt_length: promptForLog.length,
                    selected_component_type: selectedComponentType,
                    has_selection: hasSelection,
                    generation_mode: forceFullCanvas ? "full_canvas" : "selection_or_standard",
                    daily_count_at_request: currentCount,
                    daily_limit: dailyLimit,
                    created_at: now.toISOString(),
                });
            } catch (logError) {
                console.error("ai_prompts insert failed", logError);
            }
        }

        if (!openaiApiKey) return new Response(JSON.stringify({ error: "OpenAI API key not configured" }), { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } });

        const saveUsage = (count: number) => supabaseAdmin.from("ai_usage").upsert({ user_id: userId, day, count, last_request_at: now.toISOString(), updated_at: now.toISOString() }, { onConflict: "user_id,day" });

        // ─── Generation path ────────────────────────────────────────────────
        if (!hasSelection) {
            const generationMode: GenerationMode = forceFullCanvas ? "full_canvas" : "standard";
            let generated: Awaited<ReturnType<typeof buildGeneratedScreen>>;
            try {
                generated = await buildGeneratedScreen(supabaseAdmin, safePrompt, context, generationMode);
            } catch (err) {
                console.error("Generation pipeline timed out; returning emergency fallback", err);
                generated = buildEmergencyGeneratedScreen(safePrompt);
            }
            const newCount = currentCount + 1;
            await saveUsage(newCount);

            return new Response(JSON.stringify({
                components: generated.components,
                mode: generationMode === "full_canvas" ? "full_canvas" : "blocks",
                canvas_settings: generated.canvas_settings,
                ...(generated.theme ? {
                    theme: {
                        appName: generated.theme.appName,
                        accentColor: generated.theme.accentColor,
                        secondaryColor: generated.theme.secondaryColor,
                        voiceTone: generated.theme.voiceTone,
                        cornerRadiusScale: generated.theme.cornerRadiusScale,
                    }
                } : {}),
                quota: makeQuota(newCount),
            }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
        }

        // ─── Selection editing path ─────────────────────────────────────────
        const intent = classifyIntent(safePrompt);
        const selectedComponent = resolvedSelection as AnyComponent;

        if (intent !== "structure" && intent !== "content" && intent !== "wrap" && intent !== "canvas") {
            const deterministicPatched = applyDeterministicModifierEdits(selectedComponent, safePrompt);
            if (deterministicPatched) {
                const fixed = postProcessComponents([deterministicPatched])[0];
                if (fixed?.type === "Text" && selectedComponent?.type === "Text" && !promptExplicitlyChangesText(safePrompt)) {
                    const selectedProps = isObject(selectedComponent.properties) ? selectedComponent.properties : {};
                    const selectedText = selectedProps.text;
                    if (typeof selectedText === "string" && selectedText.trim().length > 0) {
                        if (!isObject(fixed.properties)) fixed.properties = {};
                        fixed.properties.text = selectedText;
                    }
                }
                const newCount = currentCount + 1;
                await saveUsage(newCount);
                return new Response(JSON.stringify({ component: fixed, mode: "component", quota: makeQuota(newCount) }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
            }
        }

        if (intent === "style" && !CONTAINER_TYPES.has(selectedComponent.type as string)) {
            const patched = await applyStylePatch(selectedComponent, safePrompt);
            if (patched) {
                const fixed = postProcessComponents([patched])[0];
                if (fixed?.type === "Text" && selectedComponent?.type === "Text" && !promptExplicitlyChangesText(safePrompt)) {
                    const selectedProps = isObject(selectedComponent.properties) ? selectedComponent.properties : {};
                    const selectedText = selectedProps.text;
                    if (typeof selectedText === "string" && selectedText.trim().length > 0) {
                        if (!isObject(fixed.properties)) fixed.properties = {};
                        fixed.properties.text = selectedText;
                    }
                }
                const newCount = currentCount + 1;
                await saveUsage(newCount);
                return new Response(JSON.stringify({ component: fixed, mode: "component", quota: makeQuota(newCount) }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
            }
        }

        const compileResult = await compileWithRepairMessages({
            messages: [
                { role: "system", content: buildSelectionSystemPrompt(selectedComponent, intent) },
                { role: "system", content: `SELECTED COMPONENT:\n${JSON.stringify(resolvedSelection)}` },
                { role: "user", content: safePrompt },
            ],
            maxAttempts: 2, model: SELECTION_MODEL, maxTokens: SELECTION_MAX_TOKENS,
        });

        if (compileResult.ok === false) {
            return new Response(JSON.stringify({ error: `Failed: ${compileResult.error}` }), { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } });
        }

        const parsedResult = compileResult.parsed as Record<string, unknown>;
        const comp = parsedResult.component as AnyComponent | undefined;
        const sel = resolvedSelection as Record<string, unknown> | undefined;
        if (comp && comp.type === "Text" && sel && sel.type === "Text") {
            const selText = isObject(sel.properties) ? sel.properties.text : undefined;
            if (typeof selText === "string" && !promptExplicitlyChangesText(safePrompt)) {
                if (!isObject(comp.properties)) comp.properties = {};
                comp.properties.text = selText;
            }
        }

        const newCount = currentCount + 1;
        await saveUsage(newCount);
        return new Response(JSON.stringify({ ...parsedResult, quota: makeQuota(newCount) }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });

    } catch (err) {
        return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } });
    }
});
